  364:     dir: &Path,
  365:     log: FoundLog,
  366:     tx: &mpsc::Sender<Result<JobLogChunk, Status>>,
  367: ) -> Result<bool, Status> {
  368:     let unreadable =
  369:         |error: std::io::Error| Status::internal(format!("reading a job log: {error}"));
  370:     let (mut file, finished) = match tokio::fs::File::open(&log.path).await {
  371:         Ok(file) => (file, log.finished),
  372:         // The run finished between listing and opening: its partial is gone
  373:         // and its finished log is in place.
  374:         Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
  375:             let dir = dir.to_path_buf();
  376:             let key = log.key.clone();
  377:             let Some(now) = tokio::task::spawn_blocking(move || job_log::find_log(&dir, &key))
  378:                 .await
  379:                 .map_err(|error| Status::internal(format!("finding a job log: {error}")))?
  380:             else {
  381:                 return Ok(true);
  382:             };
  383:             (
  384:                 tokio::fs::File::open(&now.path).await.map_err(unreadable)?,
  385:                 now.finished,
  386:             )
  387:         }
